using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class SceneTabsOperations
{
    private int Find(TabBar owner,string kind,string identity){var documents=Documents(owner);for(int i=0;i<documents.Count;i++){var document=documents[i].AsGodotDictionary();if(Kind(document)==kind&&document.GetValueOrDefault("identity","").AsString()==identity)return i;}return -1;}
    private void AddWorkspaceDocument(TabBar owner,Settings document,string icon){Documents(owner).Add(document);owner.Set("_switching",true);owner.AddTab(document["name"].AsString(),GD.Load<Texture2D>(icon));if(owner.TabCount>Documents(owner).Count)owner.MoveTab(owner.TabCount-1,Documents(owner).Count-1);ensure_new_tab(owner);owner.Set("_switching",false);open_index(owner,Documents(owner).Count-1);}
    private static string Identity(Variant value)=>value.VariantType==Variant.Type.String?ProjectSettings.GlobalizePath(value.AsString()).Replace('\\','/').SimplifyPath():value.VariantType==Variant.Type.Object&&value.AsGodotObject() is GodotObject resource?"embedded:"+resource.GetInstanceId():"";
    public bool open_simple_workspace(TabBar owner,string kind,Variant value)
    {
        if(Workspace(owner,kind)==null)return false;var resource=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;if(kind=="image"&&value.VariantType!=Variant.Type.String&&resource is not (Image or Texture2D)&&!ActorDataOperations.ScriptIs(resource,"res://Workspaces/ImageWorkspace/image_document.gd"))return false;string identity=kind=="image"?image_identity(value):Identity(value);if(identity.Length==0)return false;int found=Find(owner,kind,identity);if(found>=0){capture_current(owner);open_index(owner,found);return true;}capture_current(owner);string path=value.VariantType==Variant.Type.String?value.AsString():"";string title=path.Length>0?path.GetFile():kind switch{"model"=>"Untitled Model","environment"=>"Untitled Environment","image"=>"Untitled Image","compositing"=>resource is CompositingDocument||ActorDataOperations.ScriptIs(resource,"res://Workspaces/CompositingWorkspace/compositing_document.gd")?resource!.Get("title").AsString():"Untitled Composition",_=>"Untitled"};string icon=kind switch{"model"=>"BasicMesh.svg","image"=>"Image2D.svg",_=>"WorldEnvironment.svg"};AddWorkspaceDocument(owner,new Settings{["type"]=kind,["source"]=value,["identity"]=identity,["path"]=kind=="model"?"":path,["name"]=title,["state"]=new Settings(),["dirty"]=false},"res://resources/Images/ActorIcons/"+icon);return true;
    }
    public Settings synchronized_shader_state(Settings previous,Variant source,Variant parameters){var state=previous.Duplicate(true);if(source.VariantType==Variant.Type.Object&&source.AsGodotObject() is Shader shader)state["code"]=shader.Code;else{using var file=FileAccess.Open(source.ToString(),FileAccess.ModeFlags.Read);if(file!=null)state["code"]=file.GetAsText();}if(parameters.VariantType==Variant.Type.Dictionary){var dictionary=parameters.AsGodotDictionary();var values=dictionary.GetValueOrDefault("values",dictionary);if(values.VariantType==Variant.Type.Dictionary)state["parameters"]=values.AsGodotDictionary().Duplicate(true);if(dictionary.ContainsKey("reader")&&dictionary.ContainsKey("writer")&&!state.ContainsKey("parameters_linked"))state["parameters_linked"]=true;}return state;}
    public bool open_shader(TabBar owner,Variant source,Variant parameters){if(Workspace(owner,"shader")==null||source.VariantType!=Variant.Type.String&&!(source.VariantType==Variant.Type.Object&&source.AsGodotObject() is Shader))return false;string identity=shader_identity(source);int found=Find(owner,"shader",identity);if(found>=0){capture_current(owner);var existing=Documents(owner)[found].AsGodotDictionary();existing["source"]=source;var state=synchronized_shader_state(existing.GetValueOrDefault("state",new Settings()).AsGodotDictionary(),source,parameters);existing["state"]=state;var binding=owner.Call("_shader_binding",parameters).AsGodotDictionary();if(binding.Count>0){if(existing.GetValueOrDefault("binding",new Settings()).AsGodotDictionary().Count==0)state["parameters_linked"]=true;existing["binding"]=binding;}existing["dirty"]=false;Documents(owner)[found]=existing;open_index(owner,found);return true;}capture_current(owner);string path=source.VariantType==Variant.Type.String?source.AsString():"";var shader=source.VariantType==Variant.Type.Object?source.AsGodotObject() as Shader:null;string title=path.Length>0?path.GetFile():shader!=null&&shader.ResourceName.Length>0?shader.ResourceName:"Untitled Shader";AddWorkspaceDocument(owner,new Settings{["type"]="shader",["source"]=source,["identity"]=identity,["path"]=path,["name"]=title,["state"]=synchronized_shader_state(new Settings(),source,parameters),["binding"]=owner.Call("_shader_binding",parameters),["dirty"]=false},"res://resources/Images/ActorIcons/Shader.svg");return true;}
    public void load_shader_into_current_tab(TabBar owner,string path){int active=Active(owner);var documents=Documents(owner);if(active<0||active>=documents.Count||path.Length==0)return;var current=documents[active].AsGodotDictionary();if(Kind(current)!="shader"||current.GetValueOrDefault("path","").AsString().Length>0){open_shader(owner,path,default);return;}string identity=shader_identity(path);for(int i=0;i<documents.Count;i++)if(i!=active&&Kind(documents[i].AsGodotDictionary())=="shader"&&documents[i].AsGodotDictionary().GetValueOrDefault("identity","").AsString()==identity){open_index(owner,i);return;}current["source"]=path;current["path"]=path;current["identity"]=identity;current["name"]=path.GetFile();current["state"]=synchronized_shader_state(new Settings(),path,default);current["binding"]=new Settings();current["dirty"]=false;documents[active]=current;open_index(owner,active);}
    public bool open_scene(TabBar owner,string path){if(Timeline(owner)==null||path.Length==0)return false;string normalized=path.Replace('\\','/').SimplifyPath();var documents=Documents(owner);for(int i=0;i<documents.Count;i++)if(documents[i].AsGodotDictionary().GetValueOrDefault("path","").AsString().Replace('\\','/').SimplifyPath()==normalized){capture_current(owner);open_index(owner,i);return true;}var scene=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);if(!ActorDataOperations.ScriptIs(scene,"res://scripts/actors/core/actor_scene_data.gd"))return false;capture_current(owner);add_document(owner,scene!,path,path.GetFile().GetBaseName(),new UndoRedo());open_index(owner,documents.Count-1);return true;}
    public void new_shader(TabBar owner){var shader=new Shader{ResourceName="Untitled Shader",Code="shader_type spatial;\n\nvoid fragment() {\n    ALBEDO = vec3(0.72, 0.82, 0.9);\n    ROUGHNESS = 0.35;\n}\n"};open_shader(owner,shader,default);var workspace=Workspace(owner,"shader");if(workspace!=null){workspace.Set("requires_path",true);workspace.Get("load_shader_button").As<Control>().Show();var documents=Documents(owner);int index=Active(owner);if(index>=0&&index<documents.Count){var document=documents[index].AsGodotDictionary();document["state"]=workspace.Call("capture_state");documents[index]=document;}}}
    public void new_image(TabBar owner){var image=new KiwiImageDocument();var layer=new ImageLayerOperations().create("basic",image.Get("canvas_size").AsVector2I());image.Get("layers").AsGodotArray().Add(layer);open_simple_workspace(owner,"image",image);}
    public void new_model(TabBar owner)=>open_simple_workspace(owner,"model",new KiwiModelDocument());
    public void new_environment(TabBar owner){var document=new KiwiEnvironmentDocument();document.Call("add_terrain");open_simple_workspace(owner,"environment",document);}
}
